 const expr="JSON.stringify((()=>{const els=[...document.querySelectorAll('[data-message-author-role=\\\"assistant\\\"]')];let texts=els.slice(-3).map(e=>(e.innerText||e.textContent||'').trim().slice(0,1800));if(!texts.length){const arts=[...document.querySelectorAll('article')];texts=arts.slice(-6).map(e=>(e.innerText||e.textContent||'').trim()).filter(Boolean).slice(-3).map(x=>x.slice(0,1800))}return {title:document.title,url:location.href,assistantCount:els.length,last:texts}})())";
